import{_ as a,o as e,c as t,a2 as n}from"./chunks/framework.DqYch1Cg.js";const k=JSON.parse('{"title":"PostgreSQL 与 MySQL 对比及选型","description":"","frontmatter":{},"headers":[],"relativePath":"学习自测/19database/q_database_1-postgresql_vs_mysql.md","filePath":"学习自测/19database/q_database_1-postgresql_vs_mysql.md","lastUpdated":1794211306000}'),r={name:"学习自测/19database/q_database_1-postgresql_vs_mysql.md"};function i(l,s,o,p,h,d){return e(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="postgresql-与-mysql-对比及选型" tabindex="-1">PostgreSQL 与 MySQL 对比及选型 <a class="header-anchor" href="#postgresql-与-mysql-对比及选型" aria-label="Permalink to &quot;PostgreSQL 与 MySQL 对比及选型&quot;">​</a></h1><blockquote><p>从面试角度理解两者的差异：先讲共同点，再讲代表性优势，最后结合业务解释选型。 比较范围：PostgreSQL 与使用 InnoDB 的现代 MySQL（以 8.0 / 8.4 为例）；具体能力仍需核对版本和配置。</p></blockquote><h2 id="_1-postgresql-和-mysql-有什么区别-postgresql-的优势是什么" tabindex="-1">1. PostgreSQL 和 MySQL 有什么区别？PostgreSQL 的优势是什么？ <a class="header-anchor" href="#_1-postgresql-和-mysql-有什么区别-postgresql-的优势是什么" aria-label="Permalink to &quot;1. PostgreSQL 和 MySQL 有什么区别？PostgreSQL 的优势是什么？&quot;">​</a></h2><details class="details custom-block"><summary>参考回答</summary><p>PostgreSQL 和 MySQL 都是成熟的关系型数据库，MySQL 使用 InnoDB 时，同样支持事务、MVCC 和外键。</p><p>PG 比较突出的优势，我会从三个方面看。第一是类型和扩展能力，比如 JSONB、数组、范围类型，还有 PostGIS 这类扩展，适合比较复杂的数据建模。第二是查询和索引工具丰富，比如部分索引、表达式索引，以及适合 JSONB 等数据的 GIN 索引。第三是很多 DDL 可以放进事务里回滚，这对数据库迁移设计有帮助。</p><p>并发这块也有区别，比如 PG 默认是 Read Committed，MySQL InnoDB 默认是 Repeatable Read，快照和锁的行为不能直接照搬。</p><p>对我的学习项目，如果要做简历编辑这类业务，我会考虑用普通列保存用户、归属、版本号，把结构可变的模块内容放进 JSONB，所以倾向选择 PG。当然 MySQL 也能实现这些需求；团队已经熟悉 MySQL、业务又以常规 CRUD 为主时，继续用它也很合理。最终还要看运维成本和实际查询负载。</p></details><p><strong>回答节奏</strong>：控制在一到两分钟。先讲类型、索引和事务化 DDL，稍停一下；面试官继续关注时，再展开并发差异和项目选型。</p><p><strong>追问入口</strong>：JSONB 和普通列怎么选？两种默认隔离级别下，重复读取有什么差异？DDL 能回滚是否代表改表没有风险？</p><h2 id="先说明共同点" tabindex="-1">先说明共同点 <a class="header-anchor" href="#先说明共同点" aria-label="Permalink to &quot;先说明共同点&quot;">​</a></h2><p>两者都支持事务、约束、MVCC、索引和查询优化，现代版本也都有 JSON、CTE、窗口函数等能力。</p><p>区别主要在于具体能力、实现方式和使用体验。不要把答案说成“只有 PG 有事务、复杂查询或 JSON 索引”，也不要承诺 PG 在任何业务中都更快。</p><h2 id="五个值得展开的差异" tabindex="-1">五个值得展开的差异 <a class="header-anchor" href="#五个值得展开的差异" aria-label="Permalink to &quot;五个值得展开的差异&quot;">​</a></h2><h3 id="类型与扩展-pg-的工具比较丰富" tabindex="-1">类型与扩展：PG 的工具比较丰富 <a class="header-anchor" href="#类型与扩展-pg-的工具比较丰富" aria-label="Permalink to &quot;类型与扩展：PG 的工具比较丰富&quot;">​</a></h3><p>PG 除了常规类型，还支持数组、范围类型、JSONB 和自定义类型，也可以通过扩展增加能力，比如使用 PostGIS 处理地理空间数据。</p><p>索引方面，PG 提供 B-tree、GIN、GiST 等机制，分别适配不同的数据和查询方式。MySQL 也有 JSON、空间类型和空间索引；PG 的特色在于类型、操作符和索引机制之间有比较丰富的组合。</p><p><strong>面试表达</strong>：业务涉及半结构化数据、范围重叠或地理空间查询时，PG 往往有比较完整的工具可选。</p><h3 id="jsonb-适合部分结构可变的数据" tabindex="-1">JSONB：适合部分结构可变的数据 <a class="header-anchor" href="#jsonb-适合部分结构可变的数据" aria-label="Permalink to &quot;JSONB：适合部分结构可变的数据&quot;">​</a></h3><p>例如，简历中不同的自定义模块可能有不同字段：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;customText&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;个人优势&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;熟悉 TypeScript 全栈开发&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>PG 的 JSONB 支持丰富的查询操作符，可以按查询需求选择 GIN 或表达式索引。MySQL 的 JSON 也采用内部存储格式，并非简单的文本存储；可以通过提取字段的生成列、符合条件的函数索引，以及针对 JSON 数组的多值索引支持查询。具体支持范围取决于版本、表达式和数据类型。</p><p>结合学习场景，可以这样划分：</p><ul><li>用户 ID、简历归属、版本号等稳定字段：使用普通列，方便约束、关联和索引。</li><li>字段结构随模块变化的内容：可以考虑 JSONB。</li><li>经常过滤、关联或需要严格约束的字段：优先评估是否应提取为普通列。</li></ul><p><strong>JSONB 是关系模型的补充。</strong> 它不替代数据建模，也不是加一个 GIN 索引就能优化所有 JSON 查询；索引是否有效，要看操作符、表达式和执行计划。</p><h3 id="mvcc-与并发-默认值和实现都有差异" tabindex="-1">MVCC 与并发：默认值和实现都有差异 <a class="header-anchor" href="#mvcc-与并发-默认值和实现都有差异" aria-label="Permalink to &quot;MVCC 与并发：默认值和实现都有差异&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比项</th><th>PostgreSQL</th><th>MySQL InnoDB</th></tr></thead><tbody><tr><td>默认隔离级别</td><td>Read Committed，可配置</td><td>Repeatable Read，可配置</td></tr><tr><td>普通快照读</td><td>默认级别下，每条语句获取自己的快照</td><td>默认级别下，通常复用事务内首次一致性读建立的快照</td></tr><tr><td>MVCC 的典型实现</td><td>表中保留不同元组版本，通过可见性规则选择版本</td><td>结合 undo 日志和 Read View 查找或重建可见版本</td></tr><tr><td>旧版本清理</td><td>VACUUM / autovacuum 回收可清理的死元组空间供复用</td><td>purge 等机制清理不再需要的历史版本</td></tr><tr><td>并发控制特点</td><td>Serializable 使用 SSI 检测危险依赖，可能中止事务</td><td>Repeatable Read 下，部分范围锁定读和写操作会涉及间隙锁、next-key lock</td></tr></tbody></table><p>这里的读取对比针对<strong>普通一致性读取</strong>，不能直接套用到 <code>SELECT ... FOR UPDATE</code> 等锁定读；长事务也可能阻碍旧版本清理。PG 的常规 VACUUM 通常用于让空间复用，不意味着立刻缩小数据文件。</p><p><strong>面试表达</strong>：同一段 SQL，在两个数据库里可能有不同的可见性和锁行为。两者都可能出现锁等待或死锁，都需要控制事务长度，并按错误类型设计重试。</p><h3 id="事务化-ddl-很多结构变更可以回滚" tabindex="-1">事务化 DDL：很多结构变更可以回滚 <a class="header-anchor" href="#事务化-ddl-很多结构变更可以回滚" aria-label="Permalink to &quot;事务化 DDL：很多结构变更可以回滚&quot;">​</a></h3><p>在 PG 中，很多建表、改表操作可以放进事务：</p><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 假设 resumes 表已存在，且没有 remark 列</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BEGIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> resumes </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ADD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COLUMN remark </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ROLLBACK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>回滚后，新增列的操作也会撤销。MySQL 的许多 DDL 则会触发隐式提交，不能通过用户事务中的 <code>ROLLBACK</code> 撤销。</p><p>需要记住三个边界：</p><ul><li>PG 并非所有 DDL 都能在事务块中执行，例如 <code>CREATE DATABASE</code> 和 <code>CREATE INDEX CONCURRENTLY</code> 就有这类限制。</li><li>MySQL 的 atomic DDL 保证支持范围内的 DDL 自身及相关元数据等作为整体成功或失败，不等于用户可以用 <code>ROLLBACK</code> 撤销已经成功的 DDL。</li><li>PG 的 DDL 即使能回滚，也可能持锁；长时间不结束事务，仍可能阻塞其他请求。</li></ul><p><strong>面试表达</strong>：事务化 DDL 为迁移提供了更多选择，但迁移仍要评估锁、执行时间和上线方案。</p><h3 id="复杂查询与索引-工具丰富-性能仍需验证" tabindex="-1">复杂查询与索引：工具丰富，性能仍需验证 <a class="header-anchor" href="#复杂查询与索引-工具丰富-性能仍需验证" aria-label="Permalink to &quot;复杂查询与索引：工具丰富，性能仍需验证&quot;">​</a></h3><p>PG 提供部分索引、表达式索引、物化视图等能力，适合复杂条件查询、聚合和数据建模。比如只给“未删除记录”建立部分索引，可以围绕实际查询减少索引覆盖的数据范围。</p><p>现代 MySQL 同样支持 CTE、窗口函数和符合条件的函数索引，不能把这些当作 PG 独有能力。</p><p><strong>面试表达</strong>：PG 在高级查询和数据建模上工具比较丰富，但具体性能仍要通过执行计划、索引设计和真实负载验证。</p><h2 id="mysql-的优势-以及如何选型" tabindex="-1">MySQL 的优势，以及如何选型 <a class="header-anchor" href="#mysql-的优势-以及如何选型" aria-label="Permalink to &quot;MySQL 的优势，以及如何选型&quot;">​</a></h2><p>MySQL 在 Web 业务中使用广泛，工具、托管服务和运维生态成熟，对常规 CRUD 也能很好地满足需求。对于已经积累了 MySQL 经验和运维体系的团队，延续现有技术栈往往更省成本。</p><p>PG 也有成熟的 Web 和云服务生态，两者没有严格的应用领域分界。选择时可以依次考虑：</p><ol><li><strong>业务能力</strong>：是否依赖 JSONB 操作、范围类型、PostGIS 或特定索引等能力？</li><li><strong>数据与查询</strong>：数据怎么建模，主要查询是什么，真实负载下表现如何？</li><li><strong>团队与运维</strong>：谁负责备份恢复、监控、升级和故障处理？现有经验是否可以复用？</li></ol><p>当前仓库是 VitePress 面试知识库，上述“简历编辑服务”是用于说明选型的学习示例。面试时应结合自己实际做过的功能、测过的负载来回答，避免把计划中的能力说成已经落地。</p><h2 id="后续学习与追问" tabindex="-1">后续学习与追问 <a class="header-anchor" href="#后续学习与追问" aria-label="Permalink to &quot;后续学习与追问&quot;">​</a></h2><p>先围绕这四个问题逐步深入：</p><ol><li>哪些字段用普通列，哪些适合 JSONB？</li><li>事务中的一次读取，到底能看到哪个版本的数据？</li><li>查询为什么使用或不使用索引，如何读执行计划？</li><li>数据库迁移能否回滚，会持有什么锁？</li></ol><p>连接与停机问题可结合 <a href="/FE-prepare-interview/学习自测/18nestjs/q_nestjs_6-app_lifecycle">NestJS 应用生命周期</a>继续复习。</p><h2 id="记忆主线" tabindex="-1">记忆主线 <a class="header-anchor" href="#记忆主线" aria-label="Permalink to &quot;记忆主线&quot;">​</a></h2><p><strong>共同能力 → 类型与索引 → 并发差异 → 事务化 DDL → 结合业务选型。</strong></p><blockquote><p>来源：<a href="https://www.postgresql.org/docs/current/datatype-json.html" target="_blank" rel="noreferrer">PostgreSQL 官方文档：JSON Types</a></p></blockquote><blockquote><p>来源：<a href="https://www.postgresql.org/docs/current/transaction-iso.html" target="_blank" rel="noreferrer">PostgreSQL 官方文档：Transaction Isolation</a></p></blockquote><blockquote><p>来源：<a href="https://www.postgresql.org/docs/current/routine-vacuuming.html" target="_blank" rel="noreferrer">PostgreSQL 官方文档：Routine Vacuuming</a></p></blockquote><blockquote><p>来源：<a href="https://www.postgresql.org/docs/current/indexes.html" target="_blank" rel="noreferrer">PostgreSQL 官方文档：Indexes</a></p></blockquote><blockquote><p>来源：<a href="https://www.postgresql.org/docs/current/sql-createdatabase.html" target="_blank" rel="noreferrer">PostgreSQL 官方文档：CREATE DATABASE</a> / <a href="https://www.postgresql.org/docs/current/sql-createindex.html" target="_blank" rel="noreferrer">CREATE INDEX</a></p></blockquote><blockquote><p>来源：<a href="https://dev.mysql.com/doc/refman/8.4/en/json.html" target="_blank" rel="noreferrer">MySQL 8.4 官方文档：The JSON Data Type</a></p></blockquote><blockquote><p>来源：<a href="https://dev.mysql.com/doc/refman/8.4/en/innodb-transaction-isolation-levels.html" target="_blank" rel="noreferrer">MySQL 8.4 官方文档：InnoDB Transaction Isolation Levels</a> / <a href="https://dev.mysql.com/doc/refman/8.4/en/innodb-multi-versioning.html" target="_blank" rel="noreferrer">InnoDB Multi-Versioning</a></p></blockquote><blockquote><p>来源：<a href="https://dev.mysql.com/doc/refman/8.4/en/atomic-ddl.html" target="_blank" rel="noreferrer">MySQL 8.4 官方文档：Atomic Data Definition Statement Support</a></p></blockquote>`,55)])])}const u=a(r,[["render",i]]);export{k as __pageData,u as default};
